"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7663],{97794:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"ShredderClient","desc":"Client controller for workbench shredding interactions. Discovers placed\\nworkbenches via `CollectionService` tags, then wires each bench\'s\\n`ProximityPrompt` to a nonce-guarded two-step handshake: `PromptButtonHoldBegan`\\nfires `ReqShredderStart` to timestamp the session on the server, and the\\ncompleted `Triggered` fires `ReqShredderComplete` only if the nonce is still\\nvalid. The prompt\'s `HoldDuration` is kept in sync with the player\'s current\\nWood/Metal junk count so the progress ring reflects the expected shred time.\\nAn info notification is shown (rate-limited) when the player attempts to shred\\nwith no eligible junk.","realm":["Client"],"source":{"line":18,"path":"src/StarterPlayer/StarterPlayerScripts/ShredderClient.client.luau"}}')}}]);